package dev.redstoneengineering.block;import com.mojang.serialization.MapCodec;import dev.redstoneengineering.*;import dev.redstoneengineering.physics.*;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;public class PneumaticPipeBlock extends Block{public PneumaticPipeBlock(Properties p){super(p);}@Override public MapCodec<PneumaticPipeBlock> codec(){return RedstoneEngineering.PNEUMATIC_PIPE_CODEC.value();}@Override protected void onPlace(BlockState s,Level l,BlockPos p,BlockState o,boolean m){super.onPlace(s,l,p,o,m);if(l instanceof ServerLevel sl)PneumaticNetwork.recompute(sl,p);}@Override protected void neighborChanged(BlockState s,Level l,BlockPos p,Block b,BlockPos q,boolean m){if(l instanceof ServerLevel sl)PneumaticNetwork.recompute(sl,p);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide)pl.displayClientMessage(Component.literal("Pneumatic pressure="+PneumaticNetwork.pressure(l,p)+"/100 | "+NetworkKernel.summary(l,"pneumatic")),true);return InteractionResult.sidedSuccess(l.isClientSide);}}